// 原同时轮真实出手/扣血与显式终局；不构造World，也不以夹具战果冒正常作者银行。
#include "resident/domains/personal/personal_simultaneous_outcomes.hpp"
#include <iostream>
using namespace hanmo::resident;
namespace {
int checks=0,failures=0;
void check(bool ok,const char* name){++checks;if(!ok){++failures;std::cerr<<name<<'\n';}}
PersonalCatalog catalog(){PersonalCatalog c;c.enabled=true;PersonalObjective o;o.id="goal";o.kind="sparring";o.max_rounds=30;o.allow_withdrawal=true;c.objectives.insert(o.id,o);PersonalArena a;a.id="arena";a.width=400;a.height=300;c.arenas.insert(a.id,a);PersonalWeapon w;w.category="sword";w.minimum_range=0;w.maximum_range=100;w.arc_degrees=180;w.damage=100;w.stamina_cost=0;w.move_distance=90;c.weapons.insert("sword",w);return c;}
PersonalBattle battle(){PersonalBattle b;b.id="battle:1";b.controller_id="a";b.battlefield_id="arena";b.objective_id="goal";for(const auto& id:{StableId{"a"},StableId{"b"}}){PersonalUnit u;u.actor_id=id;u.side=id=="a"?0:1;u.position={id=="a"?100:160,100};u.heading=id=="a"?0:180;u.hp=u.initial_hp=100;u.martial=50;u.weapon_id="sword";b.units.insert(id,u);}b.ai_plans.insert("b",PersonalPlan{{160,100},180,"attack","a","",{}});return b;}
}
int main(){
 auto c=catalog();auto b=battle();CommonState seed;seed.rng.insert("duel",RngStream{123,456,{}});CommonStore common(seed,std::make_shared<CommonCatalog>());PersonalPlan attack{{100,100},0,"attack","b","",{}};
 auto old=personal_resolve(b,c,attack,common);check(old.ok,"original round resolves");if(!old.ok){std::cerr<<old.error.original.code<<'\n';return 1;}check(old.value.units.find("a")->hp==0&&old.value.units.find("b")->hp==0,"both submitted attacks survive simultaneous lethal damage");check(old.value.outcome=="defeat","unselected legacy controller priority unchanged");check(common.state().rng.find("duel")->state==456,"nonrandom old round leaves original RNG unchanged");
 c.simultaneous_outcome_objectives={"goal"};auto selected=personal_resolve(b,c,attack,common);check(selected.ok&&selected.value.outcome=="draw","selected actual same lethal round draws");check(selected.ok&&selected.value.phase=="result"&&selected.value.round==1,"one original terminal round");Integer hits=0,total=0;if(selected.ok)for(const auto& e:selected.value.last_events)if(e.action=="attack"&&e.code=="Hit"){++hits;total+=e.damage.value_or(0);}check(hits==2&&total==208,"both original damage events preserved");check(common.state().rng.find("duel")->state==456,"new outcome does not consume RNG");
 auto terminal=selected.value;check(personal_outcome(terminal,c)=="draw","cold same outcome reader selects draw");terminal.units.find("b")->hp=1;check(personal_outcome(terminal,c)=="defeat","one surviving opponent rejects draw");terminal=selected.value;terminal.units.find("b")->withdrawn_round=1;check(!personal_mutual_defeat_draw(terminal,c),"withdrawn opponent is not mutual knockdown");terminal=selected.value;terminal.units.erase("b");check(!personal_mutual_defeat_draw(terminal,c),"empty opponent set rejects draw");terminal=selected.value;auto protected_person=*terminal.units.find("a");protected_person.actor_id="ward";protected_person.protected_actor=true;terminal.units.insert("ward",protected_person);check(personal_outcome(terminal,c)=="protected_lost","protected failure precedes mutual draw");
 auto wrong=c;wrong.simultaneous_outcome_objectives={"other"};check(!validate_personal_simultaneous_outcomes(wrong).ok,"unknown objective rejected");wrong=c;wrong.simultaneous_outcome_objectives.push_back("goal");check(!validate_personal_simultaneous_outcomes(wrong).ok,"duplicate selected goal rejected");wrong=c;wrong.objectives.find("goal")->kind="escort";check(!validate_personal_simultaneous_outcomes(wrong).ok,"escort not silently broadened");
 using V=BoundaryValue;using D=V::Dict;using A=V::Array;
 V data=boundary::obj({{"required_capabilities",boundary::string_array({personal_simultaneous_outcomes_capability})}});
 V policy=boundary::obj({{"version",V{Integer{1}}},{"objective_ids",boundary::string_array({"goal"})}});
 V scenario=boundary::obj({{personal_simultaneous_outcomes_module,policy},{"dynamic_world",boundary::obj({{"profile",V{StableId{"local_society_v1"}}}})},{"enabled",boundary::obj({{"personal_objectives",boundary::string_array({"goal"})}})}});
 auto decoded=catalog();check(configure_personal_simultaneous_outcomes(data,scenario,decoded).ok&&decoded.simultaneous_outcome_objectives==std::vector<StableId>{"goal"},"explicit selected catalog decoded");auto missing=data;missing.find("required_capabilities")->data=A{};check(!configure_personal_simultaneous_outcomes(missing,scenario,decoded).ok,"missing capability rejects");auto unknown=scenario;unknown.find(personal_simultaneous_outcomes_module)->find("version")->data=Integer{2};check(!configure_personal_simultaneous_outcomes(data,unknown,decoded).ok,"future policy version rejects");auto repeated=scenario;repeated.find(personal_simultaneous_outcomes_module)->as<D>()->emplace_back("version",V{Integer{1}});check(!configure_personal_simultaneous_outcomes(data,repeated,decoded).ok,"repeated policy field rejects");check(configure_personal_simultaneous_outcomes(data,V{D{}},decoded).ok&&decoded.simultaneous_outcome_objectives.empty(),"unselected scenario clears transient policy");
 const std::vector<std::pair<StableId,StableId>> modules{{"dynamic_world","local_society_v1"},{personal_simultaneous_outcomes_module,"1"}};
 check(validate_personal_simultaneous_outcome_modules(modules,true).ok,"one explicit module accepted");check(!validate_personal_simultaneous_outcome_modules(modules,false).ok,"module without selected catalog rejects");auto badmodules=modules;badmodules.push_back(modules.back());check(!validate_personal_simultaneous_outcome_modules(badmodules,true).ok,"duplicate module rejects");badmodules=modules;badmodules.back().second="2";check(!validate_personal_simultaneous_outcome_modules(badmodules,true).ok,"unknown module rejects");check(validate_personal_simultaneous_outcome_modules({},false).ok,"old module-free profile accepted");check(!validate_personal_simultaneous_outcome_modules({{personal_simultaneous_outcomes_module,"1"}},true).ok,"native prerequisite required");
 std::cout<<"PERSONAL_SIMULTANEOUS_OUTCOMES="<<checks<<" FAILURES="<<failures<<" SCOPE=ORIGINAL_PURE_ROUND_AND_CATALOG\n";return failures?1:0;
}
